#[test] fn public_standard_stream() { let c=Config{alphabet:Alphabet::Standard,padding:Padding::Required,canonical:true}; let mut e=Encoder::new(c); assert_eq!(e.push(b"fo").unwrap(),""); assert_eq!(e.push(b"oba").unwrap(),"MZXW6YTB"); assert_eq!(e.push(b"r").unwrap(),""); assert_eq!(e.finish().unwrap(),"OI======"); let mut d=Decoder::new(c); assert_eq!(d.push("MZXW6YTB").unwrap(),b"fooba"); assert_eq!(d.push("OI======").unwrap(),b"r"); assert_eq!(d.finish(),Ok(vec![])); }
#[test] fn public_hex_stream() { let c=Config{alphabet:Alphabet::Hex,padding:Padding::Omitted,canonical:true}; let mut e=Encoder::new(c); assert_eq!(e.push(b"foo").unwrap(),""); assert_eq!(e.finish().unwrap(),"CPNMU"); let mut d=Decoder::new(c); assert_eq!(d.push("CPNMU").unwrap(),b"foo"); assert_eq!(d.finish(),Ok(vec![])); }
#[test] fn public_complete_block() { let c=Config{alphabet:Alphabet::Standard,padding:Padding::Omitted,canonical:false}; let mut e=Encoder::new(c); assert_eq!(e.push(b"rust!"),Ok("OJ2XG5BB".into())); assert_eq!(e.finish(),Ok(String::new())); let mut d=Decoder::new(c); assert_eq!(d.push("OJ2XG5BB"),Ok(b"rust!".to_vec())); assert_eq!(d.finish(),Ok(vec![])); }
#[test] fn public_closed_streams() { let c=Config{alphabet:Alphabet::Hex,padding:Padding::Required,canonical:true}; let mut e=Encoder::new(c); e.finish().unwrap(); assert_eq!(e.push(b"x"),Err(StreamError::Closed)); let mut d=Decoder::new(c); d.finish().unwrap(); assert_eq!(d.finish(),Err(StreamError::Closed)); }
